open class Superpower {
    open func activate() { fatalError("override activate()") }        // the sandbox method
    fileprivate func playSound(_ id: SoundId, volume: Double = 1.0) { engine.play(id, volume) }
    fileprivate func spawnParticles(_ kind: ParticleType, count: Int) { fx.spawn(kind, count) }
}

final class SkyLaunch: Superpower {
    override func activate() {                                       // composes primitives only
        playSound(.sproing)
        spawnParticles(.dust, count: 10)
    }
}
